using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;using ProjectChaptereight.BlogWeb.CoreLayer.DTOs.Posts;using ProjectChaptereight.BlogWeb.CoreLayer.Services.Posts;namespace ProjectChaptereight.BlogWeb.Pages{    public class SearchModel : PageModel    {        public PostFilterDto Filter { get; set; }        private readonly IPostService _postService;        public SearchModel(IPostService postService)        {            _postService = postService;        }        //SearchModel=q        public void OnGet(int pageId=1,string categorySlug=null,string q=null)        {            Filter = _postService.GetPostByFilter(new PostFilterParams()            {                PageID = pageId,                CategorySlug = categorySlug,                Take = 4,                Title = q            });        }        //GET Handler: از این برای صفحه بنیدی  استفاده کرده ایم        public IActionResult OnGetPagination(int pageId = 1, string categorySlug = null, string q = null) {            var model = _postService.GetPostByFilter(new PostFilterParams()            {                PageID = pageId,                                CategorySlug = categorySlug,                Take = 4,                Title = q            });            return Partial("_SearchView",model);        }    }   }